import { readFileSync } from "node:fs";
import { join } from "node:path";
import type { ActionSource } from "./define.js";
import { PACKAGE_ROOT } from "./options.js";

/**
 * The action registry snapshot: every packages/<package>/actions/<id>/action.json in pipeline order,
 * generated by scripts/generate-pipeline-actions.mjs (check:step-standard fails when it is stale).
 * The runtime reads the snapshot because only this package ships it; the other packages' action
 * folders are source, not published files.
 */
export const ACTIONS_SCHEMA = "clossys.pipeline-actions/1";
export const ACTIONS_FILE = "pipeline/actions.json";
export const MANIFEST_SCHEMA = "clossys.action-manifest/1";
export const MANIFEST_FILE = "pipeline/manifest.json";

export function loadActions(packageRoot = PACKAGE_ROOT): readonly ActionSource[] {
  const snapshot = JSON.parse(readFileSync(join(packageRoot, ACTIONS_FILE), "utf8")) as { schema?: string; actions?: ActionSource[] };
  if (snapshot.schema !== ACTIONS_SCHEMA || !Array.isArray(snapshot.actions)) throw new Error(`${ACTIONS_FILE} is not a ${ACTIONS_SCHEMA} snapshot; run npm run generate:pipeline-actions`);
  return snapshot.actions;
}
